mapper.select:
select o.order_name as productName, o.symbol as productType, op.income as profitAmount, op.income_rate as profitRate, CASE WHEN op.income >= 0 THEN 1 ELSE 0 END as status, op.end_time as createTime from w_order_position op inner join w_order_info o on o.order_no = op.order_no where o.user_id = #{userId,jdbcType=VARCHAR} and op.end_time is not null
and o.order_name like concat('%', #{productName,jdbcType=VARCHAR}, '%')
and o.order_no = #{productNo,jdbcType=VARCHAR}
and op.end_time >= #{startTime,jdbcType=VARCHAR}
and op.end_time <= #{endTime,jdbcType=VARCHAR}
order by op.end_time desc
